  const date = input instanceof Date ? input : new Date(input);
  if (isNaN(date.getTime())) return '';

  const pad = n => String(n).padStart(2, '0');

  const map = {
    YYYY: date.getFullYear(),
    MM: pad(date.getMonth() + 1),
    DD: pad(date.getDate()),
    HH: pad(date.getHours()),
