var tagUrl = source.key;
var tag = java.ajax(tagUrl);
var tagList = org.jsoup.Jsoup.parse(tag).select(".head_t a");
var tagSize = 0.4;
push("分类",null,1);
for (var i=2;i < tagList.length-2;i++) {
    var title = tagList[i].text();
    var url = source.key + String(tagList[i].attr("href")).replace(/(\d+).html/, `{{page}}.html`);
    title = String(title).replace(/\s/g, "");
    push(title, url, tagSize);
}
JSON.stringify(result);

